<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import AnalysisChart from './AnalysisChart.vue';
import EditorSurface from './EditorSurface.vue';
import {apiError} from './apiError';
const props=defineProps<{projectId:string;section?:string}>();
const inventory=ref<any>(null);const revision=ref(0);const pristine=ref('');const error=ref('');const message=ref('');const busy=ref(false);let request=0;
const templates=ref<any[]>([]);const selectedTemplate=ref('');const priorityResult=ref<any>(null);
const columns:Record<string,string>={reactive_limit_kvar:'无功上限 / kvar',apparent_limit_kva:'视在功率上限 / kVA',id:'编号',name:'名称',node:'接入节点',existing:'已有',available:'可用',kind:'类型',rated_kw:'额定 / kW',minimum_kw:'最小出力 / kW',startup_minutes:'启动 / min',arrival_minutes:'到位 / min',grid_forming:'构网能力',black_start:'黑启动',fuel_kwh:'燃料可发电量 / kWh',available_hours:'持续时长 / h',ramp_kw_per_minute:'爬坡 / kW/min',mobile:'移动式',power_kw:'功率 / kW',energy_kwh:'能量 / kWh',initial_soc:'初始SOC',minimum_soc:'SOC下限',maximum_soc:'SOC上限',charge_efficiency:'充电效率',discharge_efficiency:'放电效率',temperature_factor:'温度可用系数',load_class:'负荷类别',peak_kw:'峰值 / kW',reactive_kvar:'无功 / kvar',minimum_supply_ratio:'最低保供比例',target_hours:'目标时长 / h',maximum_curtailment_ratio:'最大可削减比例',interruption_allowed:'允许中断',maximum_interruption_hours:'允许中断 / h',priority:'优先级',cti:'评审CTI',rated_kva:'容量 / kVA',ratio:'变比',inrush_multiple:'涌流倍数',energization_minutes:'建压时间 / min',to_node:'末节点',line_id:'关联线路',normally_closed:'常闭',remote_control:'遥控',operation_minutes:'操作 / min',terminal_id:'终端编号',controller_id:'控制器编号',local_control:'就地控制',local_autonomy:'就地自治',covered_nodes:'覆盖节点（逗号分隔）',from_device:'首设备',to_device:'末设备',latency_ms:'延时 / ms',cost_yuan:'成本 / 元',longitude:'经度',latitude:'纬度',provenance:'来源',curve_kw:'功率曲线 / kW（逗号分隔）'};
const groups:Record<string,{label:string;defaults:any}>={
 sources:{label:'电源台账',defaults:{reactive_limit_kvar:0,apparent_limit_kva:null,kind:'光伏',rated_kw:100,minimum_kw:0,startup_minutes:0,arrival_minutes:0,grid_forming:false,black_start:false,fuel_kwh:null,available_hours:null,ramp_kw_per_minute:null,curve_kw:[]}},
 storage:{label:'储能台账',defaults:{reactive_limit_kvar:0,apparent_limit_kva:null,mobile:false,power_kw:100,energy_kwh:200,initial_soc:.8,minimum_soc:.1,maximum_soc:.95,charge_efficiency:.95,discharge_efficiency:.95,arrival_minutes:0,grid_forming:false,black_start:false,temperature_factor:1}},
 loads:{label:'负荷与保供目标',defaults:{load_class:'居民生活',peak_kw:100,reactive_kvar:0,minimum_supply_ratio:1,target_hours:48,maximum_curtailment_ratio:0,interruption_allowed:false,maximum_interruption_hours:0,priority:2,cti:null,curve_kw:[]}},
 transformers:{label:'变压器',defaults:{to_node:2,rated_kva:100,ratio:1,inrush_multiple:null,energization_minutes:0}},
 switches:{label:'开关',defaults:{line_id:1,normally_closed:true,remote_control:false,operation_minutes:1,terminal_id:null}},
 controllers:{label:'控制器',defaults:{covered_nodes:[],local_autonomy:true}},terminals:{label:'自动化终端',defaults:{controller_id:'',local_control:true}},
 communication:{label:'通信链路',defaults:{from_device:'',to_device:'',available:true,latency_ms:0,cost_yuan:0}}};
const visibleGroups=computed(()=>{
 const keys:Record<string,string[]>={
  '电源台账':['sources'],
  '储能台账':['storage'],
  '负荷与保供目标':['loads'],
  '变压器与开关':['transformers','switches'],
  '二次设备与通信':['controllers','terminals','communication']
 };
 return Object.fromEntries((keys[props.section||'']||[]).map(key=>[key,groups[key]]));
});
const group=ref('sources');const dirty=computed(()=>!!inventory.value&&JSON.stringify(inventory.value)!==pristine.value);
const economicNames:Record<string,string>={discount_rate:'折现率',lifetime_years:'寿命 / 年',investment_limit_yuan:'投资上限 / 元（空为未设）',pv_yuan_per_kw:'光伏 / 元/kW',wind_yuan_per_kw:'风电 / 元/kW',storage_power_yuan_per_kw:'储能功率 / 元/kW',storage_energy_yuan_per_kwh:'储能电量 / 元/kWh',fuel_yuan_per_kwh:'燃料 / 元/kWh',shortage_yuan_per_kwh:'缺供损失 / 元/kWh',curtailment_yuan_per_kwh:'负荷削减 / 元/kWh',annual_maintenance_yuan:'年运维 / 元/年',provenance:'成本来源'};
const priority=ref<any>({cti:.75,historical_consequence:.8,repair_hours:24,repair_reference_hours:72,disaster_hours:48,disaster_reference_hours:72,supply_kw:100,supply_reference_kw:500,interruptibility:0,curtailability:0,weights:[.2,.15,.2,.15,.15,.15],beta:.6,importance:null});
const priorityNames:Record<string,string>={cti:'已评审CTI',historical_consequence:'历史后果指标（0—1）',repair_hours:'抢修时长 / h',repair_reference_hours:'抢修参考上限 / h',disaster_hours:'灾害时长 / h',disaster_reference_hours:'灾害参考时长 / h',supply_kw:'孤岛供电能力 / kW',supply_reference_kw:'最大供电能力 / kW',interruptibility:'可中断指标（0—1）',curtailability:'可削减指标（0—1）',beta:'需求权重β',importance:'重要性分值（空为PPT分类示例）'};
const tableKeys=computed(()=>{const keys=['id','name','node','existing','available',...Object.keys(groups[group.value].defaults),'longitude','latitude','provenance'];return group.value==='communication'?['id',...Object.keys(groups.communication.defaults)]:keys});
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function read(){const token=++request;const id=props.projectId;inventory.value=null;revision.value=0;error.value='';message.value='';priorityResult.value=null;if(!id){busy.value=false;return}busy.value=true;try{const [d,t]=await Promise.all([api('/api/engineering/projects/'+id),api('/api/engineering/scenario-templates')]);if(token!==request)return;inventory.value=d.inventory;revision.value=d.revision;pristine.value=JSON.stringify(d.inventory);templates.value=t.templates;selectedTemplate.value=d.inventory.scenario_template_id||''}catch(e){if(token===request)error.value=String(e)}finally{if(token===request)busy.value=false}}
watch(()=>props.projectId,read,{immediate:true});
watch(()=>props.section,v=>{const found=Object.entries(groups).find(([,item])=>item.label===v);if(found)group.value=found[0];else if(v==='变压器与开关')group.value='transformers';else if(v==='二次设备与通信')group.value='controllers'},{immediate:true});
watch(priority,()=>priorityResult.value=null,{deep:true});
function add(){let n=1;const ids=new Set(Object.keys(groups).flatMap(k=>inventory.value[k].map((r:any)=>r.id)));while(ids.has(group.value+'-'+n))n++;const common=group.value==='communication'?{}:{name:'新'+groups[group.value].label,node:1,existing:true,available:true,longitude:null,latitude:null,provenance:''};inventory.value[group.value].push({id:group.value+'-'+n,...common,...JSON.parse(JSON.stringify(groups[group.value].defaults))})}
function edit(row:any,key:string,event:Event){const input=event.target as HTMLInputElement;if(input.type==='checkbox'){row[key]=input.checked;return}if(['curve_kw','covered_nodes'].includes(key)){row[key]=input.value.trim()?input.value.split(/[,，\s]+/).map(Number):[];return}if(input.type==='number'){row[key]=input.value===''?null:Number(input.value);return}row[key]=input.value||(['terminal_id','importance'].includes(key)?null:'')}
function fieldType(row:any,key:string){if(typeof row[key]==='boolean')return 'checkbox';if(typeof row[key]==='number'||['fuel_kwh','available_hours','ramp_kw_per_minute','inrush_multiple','apparent_limit_kva','cti','longitude','latitude'].includes(key))return 'number';return 'text'}
async function save(){const id=props.projectId,token=request;const submitted=JSON.parse(JSON.stringify(inventory.value));const submittedRevision=revision.value;busy.value=true;error.value='';try{const project=await api('/api/projects/'+id);if(token!==request)return;const d=await api('/api/engineering/projects/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_revision:project.revision,expected_revision:submittedRevision,inventory:submitted})});if(token!==request)return;inventory.value=d.inventory;revision.value=d.revision;pristine.value=JSON.stringify(d.inventory);message.value='台账已校验保存为版本 '+d.revision+'，历史版本保留。';ledgerOpen.value=false}catch(e){if(token===request)error.value=String(e)}finally{if(token===request)busy.value=false}}
function download(){const u=URL.createObjectURL(new Blob([JSON.stringify({project_id:props.projectId,revision:revision.value,inventory:inventory.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='工程台账.json';a.click();URL.revokeObjectURL(u)}
async function upload(event:Event){const input=event.target as HTMLInputElement;const token=request;try{const f=input.files?.[0];if(!f)return;if(f.size>6000000)throw Error('台账JSON不得超过6MB');const d=JSON.parse(await f.text());if(token!==request)return;const v=d.inventory||d;if(!Object.keys(groups).every(k=>Array.isArray(v[k]))||!v.economics)throw Error('文件须包含完整设备数组和economics');inventory.value=v;message.value='已载入台账草稿，请检查并校验保存。'}catch(e){if(token===request)error.value=String(e)}finally{input.value=''}}
function applyTemplate(){const t=templates.value.find(t=>t.id===selectedTemplate.value);if(!t)return;inventory.value.scenario_template_id=t.id;for(const l of inventory.value.loads){const goal=t.targets.find((g:any)=>g.load_class===l.load_class);Object.assign(l,goal);l.maximum_interruption_hours=0}message.value='已按模板更新负荷目标草稿；请核实地区参数并保存台账。未改变源荷或设备故障概率。'}
async function calculate(){const token=request;busy.value=true;error.value='';try{const d=await api('/api/engineering/priority',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(priority.value)});if(token===request)priorityResult.value=d}catch(e){if(token===request)error.value=String(e)}finally{if(token===request)busy.value=false}}

const isLedger=computed(()=>['电源台账','储能台账','负荷与保供目标','变压器与开关','二次设备与通信'].includes(props.section||''));
const ledgerOpen=ref(false);let ledgerBaseline='';
function openLedger(){ledgerBaseline=JSON.stringify(inventory.value);ledgerOpen.value=true}
function closeLedger(value:boolean){if(!value&&ledgerOpen.value&&ledgerBaseline){inventory.value=JSON.parse(ledgerBaseline);ledgerOpen.value=false}}
const ledgerKeys=computed(()=>Object.keys(visibleGroups.value));
const ledgerRows=computed(()=>ledgerKeys.value.flatMap(k=>(inventory.value?.[k]||[]).map((r:any)=>({...r,groupLabel:groups[k].label}))));
const ledgerPower=computed(()=>ledgerRows.value.map((r:any)=>typeof (r.rated_kw??r.power_kw??r.peak_kw)==='number'?(r.rated_kw??r.power_kw??r.peak_kw)/1000:null));
watch(()=>props.section,()=>{if(ledgerOpen.value)closeLedger(false)});
</script>

<template><div v-if="isLedger" class="resource-overview"><div class="actions"><strong>{{section}} · 台账版本 {{revision}}</strong><button @click="openLedger" :disabled="!inventory">打开数据编辑器</button><button @click="download" :disabled="!inventory">导出台账 JSON</button></div><p v-if="message">{{message}}</p><p v-if="!inventory">{{error||'正在读取当前工程台账…'}}</p><template v-else><p>当前 {{ledgerRows.length}} 项设备或负荷。台账与工程运行参数、优化候选资源分别维护。</p><AnalysisChart v-if="ledgerRows.length&&ledgerPower.some(v=>v!==null)" :zoom="false" :title="section+' · 记录功率'" :labels="ledgerRows.map((r:any)=>r.name||r.id)" :series="[{name:'台账记录功率',type:'bar',data:ledgerPower}]" unit="MW"/><AnalysisChart v-if="section==='储能台账'&&ledgerRows.length" :zoom="false" title="储能能量" :labels="ledgerRows.map((r:any)=>r.name||r.id)" :series="[{name:'台账记录能量',type:'bar',data:ledgerRows.map((r:any)=>typeof r.energy_kwh==='number'?r.energy_kwh/1000:null)}]" unit="MWh"/><p v-if="!ledgerRows.length" class="notice">当前台账没有记录；打开编辑器录入真实资源后保存。</p><div class="scroll"><table><tr><th>编号</th><th>名称</th><th>类别</th><th>关联节点</th></tr><tr v-for="r in ledgerRows.slice(0,8)"><td>{{r.id}}</td><td>{{r.name||'未命名'}}</td><td>{{r.groupLabel}}</td><td>{{r.node??'未记录'}}</td></tr></table></div></template></div><EditorSurface :enabled="isLedger" :open="ledgerOpen" :title="section||'台账编辑'" @update:open="closeLedger"><article><h3>{{section}}</h3><p>台账按工程独立保存并保留版本。请先保存工程网络，再保存台账；此处“保存台账”与顶部“保存工程”分别管理。台账已供“电力电量平衡 → 逐设备时序调度”使用；旧汇总平衡仍沿用原参数，不自动替换。</p><p v-if="error" class="error">{{error}}</p><p v-if="message" class="notice">{{message}}</p><p>台账版本 {{revision}} · {{dirty?'有未保存修改':'与已读取版本一致'}}</p><div class="actions"><button v-if="!isLedger" @click="save" :disabled="busy||!inventory">校验并保存台账</button><button @click="read" :disabled="busy">重新读取已保存台账</button><button @click="download" :disabled="!inventory">导出台账JSON</button><label class="button">导入台账JSON<input type="file" accept=".json" hidden @change="upload" :disabled="busy"></label></div>
<template v-if="inventory"><template v-if="section==='典型场景库'"><h3>课题1 · 11类典型保供场景</h3><p>覆盖西部县域2类、东中西乡镇6类、东中西村级3类。重现期为灾害等级标签，不是逐时设备故障概率。功率比例与时长为完整中期PPT第19页研究目标模板，需按示范区确认。</p><div class="scroll"><table><tr><th>模板</th><th>典型灾种</th><th>基本保障</th><th>居民生活</th><th>校准</th></tr><tr v-for="t in templates" :key="t.id"><td>{{t.name}}</td><td>{{t.hazard_examples.join('、')}}</td><td>{{t.targets[0].minimum_supply_ratio*100}}% / {{t.targets[0].target_hours}}h</td><td>{{t.targets[1].minimum_supply_ratio*100}}% / {{t.targets[1].target_hours}}h</td><td>未做地区校准</td></tr></table></div><div class="actions"><select v-model="selectedTemplate"><option value="">选择模板</option><option v-for="t in templates" :value="t.id">{{t.name}}</option></select><button @click="applyTemplate" :disabled="busy||!selectedTemplate">将模板目标应用到负荷草稿</button></div><p v-if="!inventory.loads.length">台账尚无负荷，请先在“数据管理 → 负荷与保供目标”建立负荷。</p></template>
<template v-else-if="section==='分类目标与优先级'"><h3>保供需求指数与综合优先级</h3><p>D=Σw·分项；P=βD+(1-β)I。完整中期PPT第16—18页。保留原公式中的1-抢修时长/上限方向。CTI采用已评审值，未擅自推定CTI权重。</p><div class="fields"><label v-for="(label,key) in priorityNames" :key="key">{{label}}<input type="number" step="any" :value="priority[key]" @input="edit(priority,key,$event)"></label></div><label>六项权重（历史后果、抢修、灾害、供电、可中断、可削减，合计1）<input class="weights" :value="priority.weights.join(',')" @change="priority.weights=($event.target as HTMLInputElement).value.split(/[,，]/).map(Number)"></label><button @click="calculate" :disabled="busy">计算需求与优先级</button><template v-if="priorityResult"><p>负荷类别：{{priorityResult.load_class}}；需求指数 {{priorityResult.demand_index.toFixed(6)}}；重要性 {{priorityResult.importance}}；综合优先级 {{priorityResult.priority_score.toFixed(6)}}</p><table><tr><th>分项</th><th>归一值</th><th>权重</th><th>贡献</th></tr><tr v-for="r in priorityResult.components"><td>{{r.name}}</td><td>{{r.value.toFixed(6)}}</td><td>{{r.weight}}</td><td>{{r.contribution.toFixed(6)}}</td></tr></table><p v-for="note in priorityResult.notes">{{note}}</p></template></template>
<template v-else-if="section==='经济参数'"><h3>工程经济参数（统一元、kW、kWh）</h3><p>默认投资与燃料数值来自界面设计PPT示例，保存前请核实；这里保存参数，不代表已完成全寿命经济性评价。</p><div class="fields"><label v-for="(label,key) in economicNames" :key="key">{{label}}<input :type="key==='provenance'?'text':'number'" step="any" :value="inventory.economics[key]" @input="edit(inventory.economics,key,$event)"></label></div></template>
<template v-else><div v-if="Object.keys(visibleGroups).length>1" class="actions"><button v-for="(g,key) in visibleGroups" :key="key" @click="group=String(key)" :class="{current:group===key}">{{g.label}}（{{inventory[key].length}}）</button></div><h3>{{groups[group].label}}</h3><p>编号全台账唯一。曲线填逗号分隔的kW值；经纬度须成对填写。遥控开关须绑定终端，终端须绑定控制器，通信链路连接控制器或终端。</p><div class="scroll"><table><thead><tr><th v-for="key in tableKeys" :key="key">{{columns[key]||key}}</th><th>操作</th></tr></thead><tbody><tr v-for="(row,i) in inventory[group]" :key="i"><td v-for="key in tableKeys" :key="key"><select v-if="key==='kind'" v-model="row[key]"><option v-for="v in ['光伏','风电','小水电','柴油机','移动发电车']">{{v}}</option></select><select v-else-if="key==='load_class'" v-model="row[key]"><option v-for="v in ['基本保障','居民生活','一般负荷']">{{v}}</option></select><input v-else :aria-label="(columns[key]||key)+' '+(i+1)" :type="fieldType(row,key)" :checked="fieldType(row,key)==='checkbox'?row[key]:undefined" :value="Array.isArray(row[key])?row[key].join(','):row[key]" step="any" @input="edit(row,key,$event)" :disabled="busy"></td><td><button @click="inventory[group].splice(i,1)" :disabled="busy">删除</button></td></tr></tbody></table></div><p v-if="!inventory[group].length">尚无{{groups[group].label}}记录。</p><button @click="add" :disabled="busy">新增{{groups[group].label}}</button></template></template></article><template #footer><button @click="closeLedger(false)">取消</button><button class="primary" @click="save" :disabled="busy||!inventory">校验并保存台账</button></template></EditorSurface></template>

<style scoped>.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.fields label{display:flex;justify-content:space-between;align-items:center;gap:8px}.fields input{width:190px}input,select{padding:8px;border:1px solid #c8dcdf;max-width:100%}td input{width:130px}td input[type=checkbox]{width:20px}.scroll{max-height:520px;overflow:auto;margin:18px 0}.weights{width:320px;margin:12px}.actions{margin:15px 0}.current{background:#087b7b;color:white}thead th{white-space:nowrap;position:sticky;top:0}@media(max-width:1000px){.fields{grid-template-columns:1fr}}</style>
